def minimumSize(nums: list[int], maxOperations: int) -> int:
    lo, hi = 1, max(nums)
    ans = hi
    while lo <= hi:
        mid = (lo + hi) // 2
        ops = sum((x - 1) // mid for x in nums)
        if ops <= maxOperations:
            ans = mid
            hi = mid - 1
        else:
            lo = mid + 1
    return ans

